template<typename T_,typename...A_>void write(const T_&X,const A_&...A){write(X);write(A...);}
}
using namespace IO;
const ll p[]={1,10,100,1000,10000,100000,1000000,10000000};
const int M=998244353,M2=1000000007;
int idx,ans;
ll n,s[10],Idx=-1;
int v[10][1000005],L[10];
inline int Del(int x){return x>=M?x-M:x;}
inline int Del1(int x){return x>=M2?x-M2:x;}
void dfs1(int x,int d){
	int u=Del(idx-x+M);
	v[d][L[d]++]=u;++idx;s[d]+=u;
	if(d==6)return;
	for(int i=0;i<10;i++)dfs1(x*10+i,d+1);
}
inline void query(int x,ll r){
	for(int i=0;i<7;i++){
		ll t=(r-x*p[i])%M;
		if(t<0)t+=M;
		int g=lower_bound(v[i],v[i]+L[i],M-t)-v[i];
		ans=(ans+s[i]+t*L[i]-1ll*M*(L[i]-g))%M2;
	}
}
void dfs2(ll x){
	if((x+1)*p[6]<=n+1&&x*p[7]>n){
		query(x,Idx+1),Idx+=idx;
		return;
	}
	++Idx;
	ans=Del1(ans+Del((Idx-x)%M+M));
	for(int i=(!x);i<10;i++)
		if(x*10+i<=n)dfs2(x*10+i);
}
signed main(){
	dfs1(0,0);
	n=read<ll>();
	dfs2(0);
	write(ans);
	flush();return 0;
}

